HTML:
```php
<!DOCTYPE html>
<html>
  <head>
    <title>My Joke Website</title>
    <style>
      #joke {
        color: #000;
      }
      #joke-button {
        background-color: blue;
        color: white;
        padding: 10px;
        font-size: 18px;
        border-radius: 5px;
      }
      #reveal-punchline {
        display: none;
        font-size: 16px;
        text-align: center;
      }
    </style>
  </head>
  <body>
    <div id="joke-container">
      <button id="joke-button">Click to reveal a joke!</button>
      <div id="reveal-punchline"></div>
    </div>
    <script>
      let jokeContainer = document.getElementById("joke-container");
      let jokeButton = document.getElementById("joke-button");
      let revealPunchline = document.getElementById("reveal-punchline");

      jokeButton.addEventListener("click", () => {
        revealPunchline.innerHTML = "Push to reveal punchline!";
        setTimeout(() => {
          revealPunchline.innerHTML = "A real joke here!";
        }, 3000);
      });
    </script>
  </body>
</html>
```
